section.pre:
@supports (color: navy) and selector(chapter > title) {
    chapter > title { color: navy; }
}

@supports-condition --has-navy {
    color: navy;
}

@supports (--has-navy) {
    chapter { color: navy; }
}

@when media(width >= 6in) and supports(color: navy) {
    chapter { color: navy; }
}
